const int buttonPin = 15;
volatile int contador = 0; // volatile porque se modifica en una ISR
void IRAM_ATTR onButtonPress() {
  contador++;               // Rutina de interrupción (ISR)
}
void setup() {
  Serial.begin(115200);
  pinMode(buttonPin, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(buttonPin), onButtonPress, FALLING);
  Serial.println("Interrupción configurada");
}

hw_timer_t *timer = NULL;
#define LED_BUILTIN 2
void IRAM_ATTR onTimer() {
  digitalWrite(LED_BUILTIN, !digitalRead(LED_BUILTIN));
}
void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
  digitalWrite(LED_BUILTIN, HIGH);
  timer = timerBegin(1000000);          // 1 MHz: 1 tick = 1 µs
  timerAttachInterrupt(timer, &onTimer);
  timerAlarm(timer, 500000, true, 0);   // cada 500000 µs
}
void loop() { }

void leerEstadoPulsador() {
  static bool estadoPulsadorAnterior = true;
  bool estadoPulsador = digitalRead(PIN_PULS);
  if (estadoPulsador != estadoPulsadorAnterior) {
    if (!estadoPulsador) Serial.println("Pulsador presionado");
    else                 Serial.println("Pulsador liberado");
    estadoPulsadorAnterior = estadoPulsador;
  }
}

