void callback(char* topic, byte* message, unsigned int length) {
  String cmd = "";
  for (unsigned int i = 0; i < length; i++) cmd += (char)message[i];
  cmd.trim();
  if (cmd == "ON23")       digitalWrite(23, HIGH);
  else if (cmd == "OFF23") digitalWrite(23, LOW);
  else Serial.println("COMANDO NO RECONOCIDO");
}

